import assert from 'node:assert/strict'
import {
  calculateMedicalPeriod,
  normalizeMedicalDate,
  countMedicalCalendarDays,
  completedMedicalYears,
  formatMedicalResult,
  prepareMedicalPeriodInput,
  describeMedicalPeriodResult
} from '../../src/utils/medical-period-calculator.js'

// Fictional inputs. Expected counts/tier values are hand-derived from A1–A13
// in the specialist review, not generated by the calculator under test.
let checks = 0
const test = (name, run) => { run(); checks++; console.log(`PASS ${name}`) }
const base = (overrides = {}) => ({
  region: 'national', locality: '杭州', asOf: '2026-03-31', hireDate: '2022-05-07',
  totalWorkYears: '8', tenYearDate: '2028-05-01', recordMode: 'intervals',
  leaveType: 'continuous', historyComplete: true, specialCircumstances: false,
  segments: [{ startDate: '2026-01-01', endDate: '2026-03-31', workDays: '' }],
  ...overrides
})
const calc = (input) => calculateMedicalPeriod(input, { today: '2026-10-09' })
const hasReason = (result, code) => result.reviewReasons.some((item) => item.code === code)
const hasError = (result, field) => result.errors.some((item) => item.field === field)
const shanghai = (overrides = {}) => base({
  region: 'shanghai', locality: '', hireDate: '2024-09-01', asOf: '2026-06-30',
  totalWorkYears: '', tenYearDate: '',
  segments: [{ startDate: '2026-06-01', endDate: '2026-06-10', workDays: '8' }],
  ...overrides
})

test('national primary conclusions separate entitlement, recorded days and accumulation scope', () => {
  const result = calc(base({ locality: '', hireDate: '2025-11-02', totalWorkYears: '1', tenYearDate: '',
    asOf: '2026-02-06', segments: [{ startDate: '2026-02-02', endDate: '2026-02-06' }] }))
  const display = describeMedicalPeriodResult(result)
  assert.equal(display.recordValue, 5)
  assert.equal(display.recordUnit, '自然日')
  assert.equal(display.thirdValue, 6)
  assert.equal(display.thirdLabel, '累计统计范围')
  assert(display.quotaDetail.includes('累计工作1年'))
  assert(display.meaning.includes('6个月内累计病休'))
  assert(display.status.title.includes('法定余额待核对'))
  const receipt = formatMedicalResult(result)
  assert(receipt.includes(display.status.title))
  assert(receipt.includes('参考折算（非核定余额）'))
  assert(!receipt.includes('剩余月数（基础参考）：暂不能确定'))
})

test('Shanghai foreground uses actual workdays and unrounded workday balance', () => {
  const result = calc(shanghai())
  const display = describeMedicalPeriodResult(result)
  assert.equal(display.recordValue, 8)
  assert.equal(display.recordUnit, '工作日')
  assert.equal(display.thirdValue, '2.61')
  assert.equal(result.usage.remainingWorkDays, 54.01)
  assert(display.recordDetail.includes('10个自然日'))
  assert(display.thirdDetail.includes('54.01'))
})

test('unknown date of total-tenure threshold cannot silently issue reference balance', () => {
  const unknown = calc(base({ totalWorkYears: '9', tenYearDate: '' }))
  assert(hasReason(unknown, 'TOTAL_TENURE_DATE_MISSING'))
  assert.equal(unknown.referenceEstimate, null)
  assert(describeMedicalPeriodResult(unknown).status.detail.includes('满10年'))
  const known = calc(base({ totalWorkYears: '9', tenYearDate: '2026-05-01' }))
  assert.equal(known.referenceEstimate.remainingDays, 0)
  const crossed = calc(base({ totalWorkYears: '9', tenYearDate: '2026-02-01' }))
  assert.equal(crossed.referenceEstimate, null)
})

test('small positive Shanghai balance is not displayed or copied as zero', () => {
  const result = calc(shanghai({ asOf: '2026-08-31', segments: [{ startDate: '2026-06-01', endDate: '2026-08-31', workDays: '62.00' }] }))
  assert.equal(result.usage.baseThresholdReached, false)
  assert.equal(result.usage.remainingWorkDays, 0.01)
  assert.equal(describeMedicalPeriodResult(result).thirdValue, '<0.01')
  assert(formatMedicalResult(result).includes('剩余不足0.01个月'))
})

test('over-budget record copy explains clamping without a false subtraction equation', () => {
  const result = calc(base({ asOf: '2026-04-02', segments: [{ startDate: '2026-01-01', endDate: '2026-04-02' }] }))
  assert.equal(result.records.naturalDays, 92)
  assert.equal(result.referenceEstimate.remainingDays, 0)
  assert(describeMedicalPeriodResult(result).referenceDetail.includes('超出参考预算2天'))
  assert(!formatMedicalResult(result).includes('− 92 = 0'))
})

test('user screenshot: 5 days gives 85 days / 2.83 months only under supplied 30-day reference', () => {
  const result = calc(prepareMedicalPeriodInput(base({ locality: '', hireDate: '2025-11-02',
    totalWorkYears: '1', tenYearDate: '', asOf: '', segments: [{ startDate: '2026-02-02', endDate: '2026-02-06' }] })))
  assert.equal(result.quota.months, 3)
  assert.equal(result.records.naturalDays, 5)
  assert.equal(result.referenceEstimate.remainingDays, 85)
  assert.equal(result.referenceEstimate.remainingMonths.toFixed(2), '2.83')
  assert.equal(result.referenceEstimate.scope, 'coze-reference-only')
  assert.equal(result.usage, null)
  assert.equal(result.maturityDate, null)
  assert(hasReason(result, 'LOCAL_RULE_PENDING'))
  assert(formatMedicalResult(result).includes('非核定余额'))
})

test('reference arithmetic cannot bypass incomplete, exceptional, summary or cross-window records', () => {
  const inputs = [base({ historyComplete: false }), base({ specialCircumstances: true }),
    base({ hireDate: '2021-02-01' }), base({ asOf: '2026-07-01' }),
    base({ recordMode: 'summary', summary: { firstDate: '2026-01-01', naturalDays: '5' } })]
  for (const input of inputs) assert.equal(calc(input).referenceEstimate, null)
})

test('gaps excluded from reference; exceeding reference budget does not emit negative balance or maturity', () => {
  const result = calc(base({ leaveType: 'segmented', segments: [
    { startDate: '2026-01-01', endDate: '2026-01-05' },
    { startDate: '2026-02-02', endDate: '2026-02-06' }
  ] }))
  assert.equal(result.referenceEstimate.usedDays, 10)
  assert.equal(result.referenceEstimate.remainingDays, 80)
  const exceeded = calc(base({ asOf: '2026-04-02', segments: [{ startDate: '2026-01-01', endDate: '2026-04-02' }] }))
  assert.equal(exceeded.referenceEstimate.remainingDays, 0)
  assert.equal(exceeded.referenceEstimate.baseThresholdReached, true)
  assert.equal(exceeded.maturityDate, null)
})

test('A1: 31 + 28 + 31 = 90; 3 months quota, 6 months accumulation', () => {
  const result = calc(base())
  assert.equal(result.ok, true)
  assert.equal(result.records.naturalDays, 90)
  assert.equal(result.quota.unitYearsAtStart, 3)
  assert.equal(result.quota.months, 3)
  assert.equal(result.quota.accumulationMonths, 6)
  assert.equal(result.usage, null)
  assert.equal(result.maturityDate, null)
  assert(hasReason(result, 'LOCAL_RULE_PENDING'))
  assert(hasReason(result, 'DAY_MONTH_PENDING'))
})
test('A2: 10 + 8 + 5 = 23; gaps 18 and 34 are excluded', () => {
  const result = calc(base({ leaveType: 'segmented', segments: [
    { startDate: '2026-03-16', endDate: '2026-03-20' },
    { startDate: '2026-01-05', endDate: '2026-01-14' },
    { startDate: '2026-02-02', endDate: '2026-02-09' }
  ] }))
  assert.equal(result.records.naturalDays, 23)
  assert.deepEqual(result.records.rows.map((row) => row.gapDays), [0, 18, 34])
  assert.deepEqual(result.records.rows.map((row) => row.inputIndex), [1, 2, 0])
  assert.equal(result.maturityDate, null)
})
test('A3: Shanghai 1 full year = 3 months; 8 / 20.67, not 20.83', () => {
  const result = calc(shanghai())
  assert.equal(result.records.naturalDays, 10)
  assert.equal(result.records.workDays, 8)
  assert.equal(result.quota.months, 3)
  assert.equal(result.quota.accumulationMonths, null)
  assert.equal(result.usage.usedMonths.toFixed(4), '0.3870')
  assert.equal(result.usage.remainingMonths.toFixed(4), '2.6130')
  assert.equal(result.maturityDate, null)
})
test('A4/A5: leap-year and same-day inclusive counts', () => {
  assert.equal(countMedicalCalendarDays('2024-02-28', '2024-03-01'), 3)
  assert.equal(countMedicalCalendarDays('2026-06-08', '2026-06-08'), 1)
  assert.equal(countMedicalCalendarDays('2026-12-31', '2027-01-01'), 2)
})
test('invalid dates do not normalize into successful dates', () => {
  for (const value of ['2026-02-29', '2026-04-31', '1900-02-29', '2026-13-01', '26-01-01', '2026011', '']) {
    assert.equal(normalizeMedicalDate(value), null, value)
  }
  assert.equal(normalizeMedicalDate('2000-02-29'), '2000-02-29')
  assert.equal(normalizeMedicalDate('2026年6月8日'), '2026-06-08')
  assert.equal(normalizeMedicalDate(' 2026/6/8 '), '2026-06-08')
  assert.equal(normalizeMedicalDate('20260608'), '2026-06-08')
})
test('A7: Shanghai full 1 year = 3, full 2 = 4', () => {
  const segments = [{ startDate: '2026-06-01', endDate: '2026-06-01', workDays: '1' }]
  assert.equal(calc(shanghai({ hireDate: '2025-06-01', asOf: '2026-06-01', segments })).quota.months, 3)
  assert.equal(calc(shanghai({ hireDate: '2024-06-01', asOf: '2026-06-01', segments })).quota.months, 4)
})
test('A8: all seven national tiers, exact anniversaries', () => {
  const tiers = [[9, 4, 3, 6], [9, 5, 6, 12], [10, 4, 6, 12], [10, 5, 9, 15],
    [15, 10, 12, 18], [20, 15, 18, 24], [25, 20, 24, 30]]
  for (const [total, unit, months, window] of tiers) {
    const result = calc(base({ asOf: '2026-10-08', hireDate: `${2026 - unit}-10-08`,
      totalWorkYears: String(total), tenYearDate: '',
      segments: [{ startDate: '2026-10-08', endDate: '2026-10-08' }] }))
    assert.equal(result.ok, true)
    assert.equal(result.quota.months, months)
    assert.equal(result.quota.accumulationMonths, window)
  }
})
test('A9: overlap and duplicate block counting, no automatic merge', () => {
  const result = calc(base({ leaveType: 'segmented', segments: [
    { startDate: '2026-01-05', endDate: '2026-01-14' },
    { startDate: '2026-01-10', endDate: '2026-01-20' }
  ] }))
  assert.equal(result.ok, false)
  assert(hasError(result, 'segments.1.startDate'))
  assert.equal(calc(base({ leaveType: 'segmented', segments: [base().segments[0], base().segments[0]] })).ok, false)
})
test('A10: unit crosses 5 years; no definitive remaining amount/date', () => {
  const result = calc(base({ hireDate: '2021-02-01' }))
  assert.equal(result.quota.months, 3)
  assert.equal(result.quota.unitYearsAtAsOf, 5)
  assert(hasReason(result, 'TENURE_CHANGE'))
  assert.equal(result.usage, null)
  assert.equal(result.maturityDate, null)
})
test('A11: records spanning potential window do not become one legal used amount', () => {
  const result = calc(base({ asOf: '2026-08-02', leaveType: 'segmented', segments: [
    { startDate: '2026-01-31', endDate: '2026-01-31' },
    { startDate: '2026-07-30', endDate: '2026-08-02' }
  ] }))
  assert.equal(result.records.naturalDays, 5)
  assert.equal(result.usage, null)
  assert(hasReason(result, 'WINDOW_REVIEW'))
})
test('A12: first day plus total days never creates fictional intervals', () => {
  const result = calc(base({ recordMode: 'summary', summary: { firstDate: '2026-01-05', naturalDays: '23', workDays: '' } }))
  assert.equal(result.ok, true)
  assert.equal(result.records.naturalDays, 23)
  assert.deepEqual(result.records.rows, [])
  assert.equal(result.records.lastDay, null)
  assert(hasReason(result, 'DISTRIBUTION_UNKNOWN'))
  assert.equal(result.maturityDate, null)
})
test('A13: 10-year anniversary is calendar-based, never days / 365.25', () => {
  assert.equal(completedMedicalYears('2016-10-08', '2026-10-07'), 9)
  assert.equal(completedMedicalYears('2016-10-08', '2026-10-08'), 10)
  assert.equal(completedMedicalYears('2021-10-08', '2026-10-08'), 5)
})
test('blank required fields block computation; blank is never zero', () => {
  const result = calc({})
  assert.equal(result.ok, false)
  assert(hasError(result, 'region'))
  assert.equal(calc(base({ totalWorkYears: '' })).ok, false)
  assert.equal(calc(base({ totalWorkYears: '0', hireDate: '2026-01-01', tenYearDate: '' })).ok, true)
})
test('date ordering, missing segments and future actual records', () => {
  for (const overrides of [
    { asOf: '2026-02-29' }, { hireDate: '2026-04-01' }, { asOf: '2026-01-20' },
    { segments: [] }, { segments: [{ startDate: '2026-01-02', endDate: '2026-01-01' }] },
    { segments: [{ startDate: '', endDate: '2026-01-01' }] }, { asOf: '2027-01-01' }
  ]) assert.equal(calc(base(overrides)).ok, false, JSON.stringify(overrides))
})
test('ten-year date must agree with reported completed total years', () => {
  assert.equal(calc(base({ tenYearDate: '2020-01-01' })).ok, false)
  assert.equal(calc(base({ totalWorkYears: '10', tenYearDate: '2028-01-01' })).ok, false)
  assert.equal(calc(base({ totalWorkYears: '2', tenYearDate: '' })).ok, false)
  assert.equal(calc(base({ totalWorkYears: '8.5' })).ok, false)
})
test('known ten-year transition is flagged', () => {
  const result = calc(base({ tenYearDate: '2026-02-01' }))
  assert(hasReason(result, 'TOTAL_TENURE_CHANGE'))
})
test('Shanghai missing workdays leaves usage unknown; explicit zero survives', () => {
  const missing = calc(shanghai({ segments: [{ startDate: '2026-06-01', endDate: '2026-06-10', workDays: '' }] }))
  assert.equal(missing.records.workDays, null)
  assert.equal(missing.usage, null)
  assert(hasReason(missing, 'WORKDAYS_MISSING'))
  const zero = calc(shanghai({ segments: [{ startDate: '2026-06-07', endDate: '2026-06-07', workDays: '0' }] }))
  assert.equal(zero.usage.usedMonths, 0)
  assert.equal(zero.usage.remainingMonths, 3)
})
test('Shanghai fractional workdays preserved, no truncation to integer', () => {
  const result = calc(shanghai({ segments: [{ startDate: '2026-06-01', endDate: '2026-06-01', workDays: '0.5' }] }))
  assert.equal(result.records.workDays, 0.5)
  assert.equal(result.usage.usedMonths.toFixed(4), '0.0242')
  assert.equal(result.usage.remainingMonths.toFixed(4), '2.9758')
})
test('workdays must be finite, nonnegative, at most inclusive natural days', () => {
  for (const value of ['-1', 'NaN', 'Infinity', '11', true, '1.001']) {
    const result = calc(shanghai({ segments: [{ startDate: '2026-06-01', endDate: '2026-06-10', workDays: value }] }))
    assert.equal(result.ok, false, String(value))
  }
})
test('Shanghai exact base threshold uses unrounded decimal arithmetic', () => {
  for (const [value, reached] of [['62.00', false], ['62.01', true], ['62.02', true]]) {
    const result = calc(shanghai({ asOf: '2026-08-31', segments: [
      { startDate: '2026-06-01', endDate: '2026-08-31', workDays: value }
    ] }))
    assert.equal(result.usage.baseThresholdReached, reached)
    assert(result.usage.remainingMonths >= 0)
    assert.equal(result.maturityDate, null)
  }
})
test('incomplete history and special circumstances prevent final balance', () => {
  const incomplete = calc(shanghai({ historyComplete: false }))
  assert.equal(incomplete.usage, null)
  assert.equal(incomplete.records.workDays, 8)
  assert(hasReason(incomplete, 'HISTORY_INCOMPLETE'))
  const special = calc(shanghai({ specialCircumstances: true }))
  assert.equal(special.usage, null)
  assert(hasReason(special, 'SPECIAL_REVIEW'))
})
test('Shanghai historical conversion and expired version prevent final balance', () => {
  const old = calc(shanghai({ asOf: '2025-10-27', segments: [{ startDate: '2025-10-20', endDate: '2025-10-27', workDays: '5' }] }))
  assert.equal(old.usage, null)
  assert(hasReason(old, 'HISTORICAL_CONVERSION'))
  const expired = calculateMedicalPeriod(shanghai({ asOf: '2030-07-01',
    segments: [{ startDate: '2030-06-20', endDate: '2030-07-01', workDays: '5' }] }), { today: '2030-07-01' })
  assert.equal(expired.quota, null)
  assert.equal(expired.usage, null)
  assert(hasReason(expired, 'RULE_DATE_UNSUPPORTED'))
})
test('Feb 29 anniversary legal choice is flagged and prevents final usage', () => {
  const result = calc(shanghai({ hireDate: '2024-02-29', asOf: '2026-03-01',
    segments: [{ startDate: '2026-02-28', endDate: '2026-03-01', workDays: '1' }] }))
  assert(hasReason(result, 'LEAP_ANNIVERSARY'))
  assert.equal(result.usage, null)
})
test('unknown region provides record counts, not an invented nationwide quota', () => {
  const result = calc(base({ region: 'other', totalWorkYears: '' }))
  assert.equal(result.ok, true)
  assert.equal(result.quota, null)
  assert.equal(result.records.naturalDays, 90)
  assert.equal(result.usage, null)
  assert(hasReason(result, 'REGION_UNSUPPORTED'))
  assert.equal(calc(base({ region: 'invalid' })).ok, false)
})
test('adjacent intervals accepted; continuous mode cannot discard multiple rows', () => {
  const segments = [{ startDate: '2026-01-01', endDate: '2026-01-10' },
    { startDate: '2026-01-11', endDate: '2026-01-20' }]
  assert.equal(calc(base({ leaveType: 'segmented', segments })).records.naturalDays, 20)
  assert.equal(calc(base({ leaveType: 'continuous', segments })).ok, false)
})
test('summary cannot exceed elapsed span; cannot provide fractional natural days', () => {
  for (const days of ['87', '0', '-1', '23.5', '']) {
    assert.equal(calc(base({ recordMode: 'summary', summary: { firstDate: '2026-01-05', naturalDays: days } })).ok, false)
  }
})
test('hostile input types fail safely instead of throwing', () => {
  for (const value of [null, undefined, 123, [], 'input', { segments: 'text' }, base({ segments: [null] }), base({ historyComplete: 'false' })]) {
    assert.equal(calc(value).ok, false)
  }
})
test('same inputs give same result; inputs and result snapshots do not share mutable references', () => {
  const input = shanghai()
  const original = structuredClone(input)
  const result = calc(input)
  assert.deepEqual(input, original)
  assert.deepEqual(result, calc(input))
  input.segments[0].workDays = '1'
  assert.equal(result.input.segments[0].workDays, 8)
  result.rule.sources[0].title = 'modified'
  assert.notEqual(calc(original).rule.sources[0].title, 'modified')
})
test('copy receipt includes inputs, counts, rule references and pending conclusions', () => {
  const text = formatMedicalResult(calc(shanghai()))
  for (const phrase of ['2026-06-30', '2024-09-01', '20.67', '0.39', '2.61', 'https://', '届满日期', '不预测未来届满日']) assert(text.includes(phrase), phrase)
  assert.equal(formatMedicalResult(calc({})), '')
})

test('Shanghai three-field summary preserves unknown dates and natural days', () => {
  const result = calc(shanghai({ recordMode: 'summary', summary: { workDays: '8' } }))
  assert.equal(result.ok, true)
  assert.equal(result.records.firstDay, null)
  assert.equal(result.records.lastDay, null)
  assert.equal(result.records.naturalDays, null)
  assert.equal(result.records.workDays, 8)
  assert.deepEqual(result.records.rows, [])
  assert.equal(result.quota.months, 3)
  assert.equal(result.quota.referenceDate, '2026-06-30')
  assert.equal(result.quota.referenceBasis, 'as-of')
  assert.equal(result.usage, null)
  assert(hasReason(result, 'FIRST_DATE_MISSING'))
  assert(!formatMedicalResult(result).includes('null'))
})
test('Shanghai summary zero is explicit; blank, bad units and impossible totals fail', () => {
  for (const workDays of ['', '-1', '1.234', 'Infinity', '1000']) {
    const result = calc(shanghai({ recordMode: 'summary', summary: { workDays } }))
    assert.equal(result.ok, false, workDays)
    assert(hasError(result, 'summary.workDays'))
  }
  const result = calc(shanghai({ recordMode: 'summary', summary: { workDays: '0' } }))
  assert.equal(result.ok, true)
  assert.equal(result.records.workDays, 0)
  assert.equal(result.usage, null)
})
test('optional Shanghai dates are validated and restore a dated reference without inventing days', () => {
  const result = calc(shanghai({ recordMode: 'summary', summary: { firstDate: '2026-06-01', workDays: '8' } }))
  assert.equal(result.ok, true)
  assert.equal(result.quota.referenceDate, '2026-06-01')
  assert.equal(result.quota.referenceBasis, 'first-day')
  assert.equal(result.records.naturalDays, null)
  assert.equal(result.usage.remainingMonths.toFixed(4), '2.6130')
  for (const firstDate of ['2026-02-30', '2026-07-01', '2024-08-31']) {
    assert.equal(calc(shanghai({ recordMode: 'summary', summary: { firstDate, workDays: '8' } })).ok, false)
  }
  assert.equal(calc(shanghai({ recordMode: 'summary', summary: { firstDate: '2026-06-29', workDays: '8' } })).ok, false)
})
test('Shanghai summary provided natural days remain checked against count and known horizon', () => {
  for (const summary of [{ naturalDays: '4', workDays: '8' }, { naturalDays: '1000', workDays: '8' },
    { naturalDays: '0', workDays: '0' }, { naturalDays: '2.5', workDays: '1' }]) {
    assert.equal(calc(shanghai({ recordMode: 'summary', summary })).ok, false)
  }
})

console.log(`Medical period: ${checks} cases passed.`)
